(1,-1,$m258$قرار رئيس مجلس الوزراء 1316/2005 > مواد الإصدار > المادة 1 من القرار$m258$,$m258$يعمل بأحكام اللائحة التنفيذية لقانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005 المرفقة .$m258$,'680c3b77a493364fdf0f011d26c3649b'),
(2,-1,$m258$قرار رئيس مجلس الوزراء 1316/2005 > مواد الإصدار > المادة 2 من القرار$m258$,$m258$ينشر هذا القرار فى الجريدة الرسمية ، ويعمل به اعتباراً من اليوم التالى لتاريخ نشره .
صدر برئاسة مجلس الوزراء فى 11 رجب سنة 1426 هـ ( الموافق 16 أغسطس سنة 2005م ) .
رئيس مجلس الوزراء
دكتور / أحمد نظيف$m258$,'733155fa1fe828080a2f0914e1bc0372'),
(1,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الأول: أحكام عامة > المادة 1$m258$,$m258$فى تطبيق أحكام هذه اللائحة يقصد بالقانون قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005 ، وبالوزير المختص رئيس مجلس الوزراء .
كما يقصد بالجهاز جهاز حماية المنافسة ومنع الممارسات الاحتكارية المنشأ طبقاً لأحكام القانون ، وبمجلس الإدارة مجلس إدارة جهاز حماية المنافسة ومنع الممارسات الاحتكارية .$m258$,'a10da068fcfa11149d745c6dfaafb2b7'),
(2,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الأول: أحكام عامة > المادة 2$m258$,$m258$تكون ممارسة النشاط الاقتصادى على النحو الذى لا يؤدى إلى منع حرية المنافسة أو تقييدها أو الإضرار بها ، وذلك كله وفق أحكام القانون وهذه اللائحة .$m258$,'6ed4fa1ea35e2ea2693e1ce99c0387e4'),
(3,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الأول: أحكام عامة > المادة 3$m258$,$m258$تسرى أحكام القانون وهذه اللائحة على الأفعال ، بما فيها الممارسات أو العقود أو الاتفاقات ، التى تشكل جرائم طبقاً للقانون والتى ترتكب فى الخارج إذا ترتب عليها منع حرية المنافسة أو تقييدها أو الإضرار بها فى مصر .$m258$,'ed17670ec25e8abc9b80fd12693b2860'),
(4,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الثانى: تعاريف > المادة 4$m258$,$m258$فى تطبيق أحكام القانون وهذه اللائحة ، يقصد بكل من العبارات والكلمات الواردة فى المواد التالية المعنى المبين لها فى هذه المواد .$m258$,'33312165e0ab69454ec819c735c2c81e'),
(5,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الثانى: تعاريف > المادة 5 (الأشخاص)$m258$,$m258$يقصد بالأشخاص ، الأشخاص الطبيعيون والأشخاص الاعتبارية والكيانات الاقتصادية والاتحادات والروابط والتجمعات المالية وتجمعات الأشخاص على اختلاف طرق تأسيسها ، وذلك أياً كانت طرق تمويل هذه الأشخاص أو جنسياتها أو مراكز إدارتها أو المراكز الرئيسية لأنشطتها .
ويعد من الأشخاص المشار إليها فى الفقرة الأولى ، الأطراف المرتبطة المكونة من شخصين أو أكثر لكل منها شخصية قانونية مستقلة ، تكون غالبية أسهم أو حصص أحدها مملوكة مباشرة أو بطريق غير مباشر للطرف الآخر أو تكون مملوكة لطرف واحد .
كما يعد من هذه الأطراف المرتبطة الشخص الخاضع أو الأشخاص الخاضعون للسيطرة الفعلية لشخص آخر . ويقصد بهذه السيطرة الفعلية كل وضع أو اتفاق أو ملكية لأسهم أو حصص أياً كانت نسبتها ، وذلك على نحو يؤدى إلى التحكم فى الإدارة أو فى اتخاذ القرارات .$m258$,'65a2985265fc80db50e077c85232ef77'),
(6,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الثانى: تعاريف > المادة 6 (السوق المعنية)$m258$,$m258$يقصد بالسوق المعنية السوق التى تقوم على عنصرين هما المنتجات المعنية والنطاق الجغرافى ، ويتحدد كل منهما على النحو الآتى :
أولا - المنتجات المعنية : هى المنتجات التى يعد كل منها ، من وجهة نظر المستهلك ، بديلاً عملياً وموضوعياً للآخر ، ويؤخذ فى هذا التحديد ، على الأخص ، بأى من المعايير الآتية :
1 - تماثل المنتجات فى الخواص وفى الاستخدام .
2 - مدى إمكانية تحول المشترين عن المنتج إلى منتج آخر نتيجة للتغير النسبى فى السعر أو فى أية عوامل تنافسية أخرى .
3 - ما إذا كان البائعون يتخذون قراراتهم التجارية على أساس تحول المشترين عن المنتجات إلى منتجات أخرى نتيجة التغير النسبى فى السعر أو فى العوامل التنافسية الأخرى .
4 - السهولة النسبية التى يمكن بها للأشخاص الآخرين دخول سوق المنتج .
5 - مدى توافر المنتجات البديلة أمام المستهلك .
ثانيا - النطاق الجغرافى : هو المنطقة الجغرافية التى تتجانس فيها ظروف التنافس ، وفى هذا الصدد يؤخذ فى الاعتبار فرص التنافس المحتملة ، وأى من المعايير الآتية :
1 - مدى القدرة على انتقال المشترين بين مناطق جغرافية نتيجة التغيرات النسبية فى الأسعار أو فى العوامل التنافسية الأخرى .
2 - ما إذا كان البائعون يتخذون قراراتهم التجارية على أساس انتقال المشترين بين المناطق الجغرافية المختلفة نتيجة التغيرات النسبية فى الأسعار أو فى العوامل التنافسية الأخرى .
3 - السهولة النسبية التى يستطيع بمقتضاها أشخاص آخرون دخول السوق المعنية .
4 - تكاليف النقل بين المناطق الجغرافية ، بما فى ذلك تكلفة التأمين والوقت اللازم لتزويد المنطقة الجغرافية بالمنتجات المعنية من أسواق أو من مناطق جغرافية أخرى أو من الخارج .
5 - الرسوم الجمركية والقيود غير الجمركية على المستويين المحلى والخارجى .$m258$,'2912b6583efb734907ebe7e6386ef171'),
(7,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الثانى: تعاريف > المادة 7 (السيطرة)$m258$,$m258$تتحقق سيطرة شخص على سوق معنية بتوافر العناصر الآتية :
1 - زيادة حصة الشخص على ( 25% ) من السوق المعنية ، ويكون حساب هذه الحصة على أساس عنصرى هذا السوق من المنتجات المعنية والنطاق الجغرافى معاً ، وذلك خلال فترة زمنية معينة .
2 - قدرة الشخص على إحداث تأثير فعال فى أسعار المنتجات أو فى حجم المعروض منها بالسوق المعنية .
3 - عدم قدرة الأشخاص المنافسين للشخص على الحد من تأثيره الفعال على الأسعار أو على حجم المعروض من المنتجات بالسوق المعنية .$m258$,'56e439c5800b21e3964a62d009f54859'),
(8,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الثانى: تعاريف > المادة 8 (التأثير الفعال)$m258$,$m258$يكون الشخص ذا تأثير فعال على أسعار المنتجات أو حجم المعروض منها بالسوق المعنية إذا كانت له القدرة من خلال ممارساته المنفردة على تحديد أسعار تلك المنتجات أو حجم المعروض منها بهذه السوق دون أن تكون لمنافسيه القدرة على منع هذه الممارسات ، وذلك بمراعاة العوامل الآتية :
( أ ) حصة الشخص فى السوق المعنية ووضعه بالنسبة لباقى المتنافسين .
( ب ) تصرفات الشخص فى السوق المعنية فى الفترة السابقة .
( جـ ) عدد الأشخاص المتنافسة فى السوق المعنية وتأثيرها النسبى على هيكل هذه السوق .
( د ) مدى قدرة كل من الشخص ومنافسيه على الوصول إلى المواد اللازمة للإنتاج .
( هـ ) وجود عقبات لدخول أشخاص آخرين إلى السوق المعنية .$m258$,'ecf5397390381dbb46d2324e9f2b5a94'),
(9,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الأول: أحكام عامة وتعاريف > الفصل الثانى: تعاريف > المادة 9 (الأشخاص المتنافسة)$m258$,$m258$يقصد بالأشخاص المتنافسة ، الأشخاص الذين يكون بمقدور أى منهم ممارسة ذات النشاط فى السوق المعنية فى الحال أو فى المستقبل .$m258$,'7f3e0c9e12217eb5515339aa0ddc2b86'),
(10,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الثانى: الاتفاقات والتعاقدات بين أشخاص متنافسة > المادة 10$m258$,$m258$تشمل الاتفاقات والتعاقدات التى تتم بين الأشخاص المتنافسة فى السوق المعنية ، الاتفاقات والتعاقدات المكتوبة والشفوية .$m258$,'6eca03ef7cee0d314597b92de9469abd'),
(11,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الثانى: الاتفاقات والتعاقدات بين أشخاص متنافسة > المادة 11$m258$,$m258$يحظر الاتفاق أو التعاقد بين أشخاص متنافسة فى أية سوق معنية إذا كان من شأن الاتفاق أو التعاقد إحداث أى مما يأتى :
( أ ) رفع أو خفض أو تثبيت أسعار البيع أو الشراء للمنتجات محل التعامل . ويدخل فى تحديد السعر ، العائد المستحق على الأقساط ومدة الضمان وخدمات ما بعد البيع وغيرها من الشروط التعاقدية المؤثرة فى قرار الشراء أو البيع .
( ب ) اقتسام أسواق المنتجات أو تخصيصها على أساس من المناطق الجغرافية أو مراكز التوزيع أو نوعية العملاء أو السلع أو المواسم أو الفترات الزمنية .
( جـ ) التنسيق فيما يتعلق بالتقدم أو الامتناع عن الدخول فى المناقصات والمزايدات والممارسات وسائر عروض التوريد . ويسترشد فى قيام التنسيق ، على الأخص ، بما يأتى :
1 - تقديم عطاءات متطابقة ، ويشمل ذلك ، الاتفاق على قواعد مشتركة لحساب الأسعار أو تحديد شروط العطاءات .
2 - الاتفاق حول الشخص الذى سيتقدم بالعطاء ، ويشمل ذلك ، الاتفاق مسبقاً على الشخص الذى يرسو عليه العطاء سواء بالتناوب أو على أساس جغرافى أو على أساس تقاسم العملاء .
3 - الاتفاق حول تقديم عطاءات صورية .
4 - الاتفاق على منع شخص من الدخول أو المشاركة فى تقديم عطاءات .
( د ) تقييد عمليات التصنيع أو التوزيع أو التسويق أو الحد من توزيع الخدمات أو نوعها أو حجمها أو وضع شروط أو قيود على توفيرها .$m258$,'de2691bea707511dc5ce8f91a5992c49'),
(12,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الثالث: الاتفاق أو التعاقد بين شخص وأى من مورديه أو من عملائه > المادة 12$m258$,$m258$يحظر الاتفاق أو التعاقد بين الشخص وأى من مورديه أو من عملائه ، إذا كان من شأن الاتفاق أو التعاقد الحد من المنافسة .
ويكون تقدير ما إذا كان الاتفاق أو التعاقد بين الشخص وأى من مورديه أو عملائه من شأنه الحد من المنافسة ، بناء على الفحص الذى يجريه الجهاز لكل حالة على حدة ، وذلك فى ضوء العوامل الآتية :
1 - تأثير الاتفاق أو التعاقد على حرية المنافسة فى السوق .
2 - وجود فوائد تعود على المستهلك من الاتفاق أو التعاقد .
3 - اعتبارات المحافظة على جودة المنتج أو سمعته ، ومقتضيات الأمن والسلامة ، وذلك كله على النحو الذى لا يضر بالمنافسة .
4 - مدى توافق شروط الاتفاق أو التعاقد مع الأعراف التجارية المستقرة فى النشاط محل الفحص .$m258$,'fdee5349ab582ac815e88c2700259c98'),
(13,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الرابع: إساءة استخدام السيطرة على سوق معنية > المادة 13$m258$,$m258$يحظر على من تكون له السيطرة على سوق معنية القيام بأى مما يأتى :
( أ ) أى فعل من شأنه أن يؤدى إلى عدم التصنيع أو الإنتاج أو التوزيع لمنتج ، بصورة كلية أو جزئية ، لفترة أو فترات محددة ويقصد بالفترة أو الفترات المحددة تلك التى تكفى لحدوث منع لحرية المنافسة أو تقييدها أو الإضرار بها .
( ب ) الامتناع عن إبرام صفقات بيع أو شراء منتج مع أى شخص أو وقف التعامل معه على نحو يؤدى إلى الحد من حريته فى دخول السوق أو الخروج منه فى أى وقت ، بما فى ذلك فرض شروط مالية أو التزامات أو شروط تعاقدية تعسفية أو غير مألوفة فى النشاط محل التعامل .
ولا يعد الامتناع عن إبرام الصفقات مع أى شخص أو وقف التعامل معه محظوراً إذا وجدت له مبررات تتعلق بعدم قدرة هذا الشخص على الوفاء بالتزاماته الناشئة عن العقد .
( جـ ) أى فعل من شأنه أن يؤدى إلى الاقتصار على توزيع منتج دون غيره ، على أساس مناطق جغرافية أو مراكز توزيع أو عملاء أو مواسم أو فترات زمنية وذلك بين أشخاص ذوى علاقة رأسية . ويقصد بالعلاقة الرأسية العلاقة بين الشخص المسيطر وأى من مورديه أو بينه وبين أى من عملائه .
( د ) تعليق إبرام عقد أو اتفاق بيع أو شراء لمنتج على شرط قبول التزامات أو منتجات تكون بطبيعتها أو بموجب الاستخدام التجارى للمنتج غير مرتبطة به أو بمحل التعامل الأصلى أو الاتفاق .
( هـ ) التمييز بين بائعين أو مشترين تتشابه مراكزهم التجارية فى أسعار البيع أو الشراء أو فى شروط التعامل ، وذلك على نحو يؤدى إلى إضعاف القدرة التنافسية لبعضهم أمام البعض الآخر أو يؤدى إلى إخراج بعضهم من السوق .
( و ) الامتناع بصفة كلية أو جزئية عن إنتاج أو إتاحة منتج شحيح ، متى كان إنتاجه أو إتاحته ممكناً اقتصادياً .
ويقصد بالمنتج الشحيح المنتج الذى لا يلبى المتاح منه سوى جزء ضئيل من حجم الطلب فى السوق المعنية .
( ز ) أن يشترط الشخص المسيطر على المتعاملين معه ألا يتيحوا لشخص منافس له استخدام ما يحتاجه من مرافقهم أو خدماتهم ، رغم أن إتاحة هذا الاستخدام ممكن اقتصادياً .
ويعد من هذه المرافق والخدمات تلك المملوكة للمتعاملين مع الشخص المسيطر ملكية خاصة ، وتكون لا غنى عنها للأشخاص المنافسين له للدخول أو البقاء فى السوق .
( ح ) بيع المنتجات بسعر يقل عن تكلفتها الحدية أو متوسط تكلفتها المتغيرة .
ويقصد بالتكلفة الحدية نصيب الوحدة من المنتجات من إجمالى التكاليف خلال فترة زمنية محددة . كما يقصد بالتكلفة المتغيرة التكلفة التى تتغير بتغير حجم ما يقدمه الشخص من منتجات خلال فترة زمنية محددة .
كما يقصد بمتوسط التكلفة المتغيرة إجمالى التكاليف المتغيرة مقسوماً على عدد وحدات من المنتجات .
ويراعى عند تحديد ما إذا كان المنتج يتم بيعه بسعر يقل عن تكلفته الحدية أو متوسط تكلفته المتغيرة ما يأتى :
1 - ما إذا كان البيع يؤدى إلى إخراج أشخاص منافسين للشخص المسيطر من السوق .
2 - ما إذا كان البيع يؤدى إلى منع أشخاص منافسين للشخص المسيطر من الدخول إلى السوق .
3 - ما إذا كان يترتب على البيع قدرة الشخص المسيطر على رفع الأسعار بعد إخراج الأشخاص المنافسين له من السوق .
4 - ما إذا كانت الفترة الزمنية لبيع المنتج بسعر يقل عن تكلفته الحدية أو متوسط تكلفته المتغيرة تؤدى إلى تحقيق أى مما سبق .
( ط ) إلزام الشخص المسيطر لأى مورد بعدم التعامل مع شخص منافس له .
ويقصد بعدم التعامل امتناع المورد عن التعامل مع الشخص المنافس بصورة كلية أو تخفيض حجم التعامل معه إلى الحد الذى يؤدى إلى إخراجه من السوق أو إلى منع المنافسين المحتملين من الدخول إلى السوق .$m258$,'4165967cd97fabc9a94743ab1dfa937e'),
(14,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الأول: المرافق العامة > المادة 14$m258$,$m258$لا تسرى أحكام القانون وهذه اللائحة بالنسبة للمرافق العامة التى تديرها الدولة .
ولا تخضع القرارات والاتفاقات والعقود والأعمال بالنسبة إلى هذه المرافق العامة التى تديرها الدولة لأى من أحكام الحظر المنصوص عليها فى المواد ( 6 ) ، ( 7 ) ، ( 8 ) من القانون .$m258$,'837deca8eefca4a4baa3818e132906f9'),
(15,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الأول: المرافق العامة > المادة 15$m258$,$m258$لكل شركة من الشركات الخاضعة لأحكام القانون الخاص تتولى إدارة مرفق عام ، قبل إبرام اتفاقات أو عقود أو القيام بأعمال تتعلق بنشاط هذا المرفق وتدخل فى نطاق حالات الحظر المنصوص عليها فى المواد ( 6 ) ، ( 7 ) ، ( 8 ) من القانون ، أن تطلب من الجهاز إخراج كل هذه الاتفاقات أو العقود أو الأعمال أو بعضها من الحظر إذا كان من شأنها تحقيق المصلحة العامة أو تحقيق منافع للمستهلك تفوق آثار الحد من حرية المنافسة .$m258$,'a269aabe742431c1efb98f041a725242'),
(16,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الأول: المرافق العامة > المادة 16$m258$,$m258$يكون تقديم الطلب المشار إليه فى المادة ( 15 ) من هذه اللائحة والبت فيه وفقاً للضوابط والإجراءات الآتية :
1 - يقدم الطلب كتابة إلى رئيس مجلس إدارة الجهاز ، وذلك قبل إبرام الاتفاق أو العقد أو القيام بالعمل محل الطلب ، على أن يتضمن الطلب عرضاً وافياً لأسبابه وبياناً للمصلحة العامة التى يحققها الاتفاق أو العقد أو العمل ، أو ما يؤدى إليه من منافع للمستهلك ، ويكون الطلب مشفوعاً بالأسانيد المؤيدة له .
2 - يعرض رئيس مجلس الإدارة الطلب على المجلس لنظره فى أول اجتماع تال أو فى الاجتماع الذى يحدده رئيس المجلس عند الاقتضاء .
3 - لمجلس الإدارة أن يحيل الطلب إلى الإدارة المختصة بالجهاز لدراسته وإعداد تقرير بشأنه خلال المدة التى يحددها بما لا يجاوز ثلاثين يوماً ، ويجوز للمجلس مد هذه المدة بما لا يجاوز ثلاثين يوماً أخرى بناء على عرض المدير التنفيذى للجهاز .
4 - للإدارة المختصة طلب معلومات وبيانات إضافية من ذوى الشأن أو من غيرهم وعقد جلسات استماع يدعى مقدم الطلب لحضورها .
5 - تقوم الإدارة المختصة بتقديم تقريرها فى شأن الطلب إلى المدير التنفيذى لعرضه على مجلس الإدارة فى أول جلسة تالية لانتهاء التقرير ، وعلى مجلس الإدارة أن يبت فى الطلب خلال ثلاثين يوماً من تاريخ عرضه عليه .
6 - يجب أن يستند قرار مجلس إدارة الجهاز بالموافقة على الإخراج من نطاق الحظر إلى تحقيق مصلحة عامة أو منافع للمستهلك تفوق آثار الحد من حرية المنافسة ، وإلا تعين رفض الطلب ، ويجوز أن يتضمن القرار بالموافقة تكليف الطالب بأمر أو بامتناع .
7 - يتولى المدير التنفيذى للجهاز إبلاغ الطالب بقرار المجلس وذلك بموجب كتاب موصى عليه مصحوب بعلم الوصول ويتعين أن يكون القرار الصادر بالرفض مسبباً .$m258$,'0697c3c3df98c1b785c9e610dec68073'),
(17,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الأول: المرافق العامة > المادة 17$m258$,$m258$تكون موافقة الجهاز على الإخراج من نطاق الحظر سارية لمدة سنتين ، ويجوز تجديدها بناء على طلب يتقدم به صاحب الشأن للجهاز قبل ستين يوماً من نهاية المدة . وينظر الجهاز طلب التجديد وفقاً لذات الأحكام والإجراءات المنصوص عليها فى المادة ( 16 ) من هذه اللائحة .$m258$,'682b1f9f1c5a88f3c6abb5b192ca0f6c'),
(18,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الثانى: المنتجات الأساسية > المادة 18$m258$,$m258$يجوز بقرار من مجلس الوزراء تحديد سعر بيع منتج أساسى أو أكثر لفترة زمنية محددة وذلك بعد أخذ رأى الجهاز .$m258$,'2f302b7a94dcecbcd3b52b02a368a632'),
(19,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الثانى: المنتجات الأساسية > المادة 19$m258$,$m258$يتولى الجهاز إجراء الدراسات اللازمة لممارسة مجلس الوزراء اختصاصه المنصوص عليه فى المادة ( 10 ) من القانون فى شأن تحديد أسعار بيع المنتجات الأساسية وإعداد التقارير الخاصة برأى الجهاز فى هذا الشأن .$m258$,'f1d339423e8e86e4833d2c107b8471f0'),
(20,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب الخامس: المرافق العامة والمنتجات الأساسية > الفصل الثانى: المنتجات الأساسية > المادة 20$m258$,$m258$لا يعتبر أى اتفاق تبرمه الحكومة بقصد تطبيق أسعار بيع المنتجات الأساسية التى يتم تحديدها وفقاً لأحكام المادة ( 10 ) من القانون نشاطاً ضاراً بالمنافسة .$m258$,'edb7f379bb0fe5e193c3ab3eb5a6f334'),
(21,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الأول: اجتماعات مجلس إدارة الجهاز ونظام العمل فيه > المادة 21$m258$,$m258$يتولى إدارة الجهاز مجلس إدارة يتكون من رئيس وأربعة عشر عضواً ، يشكل وفقاً لأحكام المادة ( 12 ) من القانون ، ويكون لمجلس الإدارة أمانة يصدر بتشكيلها وبنظام العمل فيها قرار من المجلس .$m258$,'d2b83faa16db1eb9bc793a2260fc67bb'),
(22,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الأول: اجتماعات مجلس إدارة الجهاز ونظام العمل فيه > المادة 22$m258$,$m258$يجتمع مجلس الإدارة بدعوة من رئيسه مرة على الأقل كل شهر وكلما دعت الضرورة ، وتوجه الدعوة إلى الاجتماع كتابة ، وذلك قبل اليوم المحدد له بأربعة أيام على الأقل ويرفق بالدعوة جدول الأعمال .
وتكون اجتماعات المجلس صحيحة بحضور عشرة من أعضائه على الأقل ، وتصدر قراراته بأغلبية أعضائه .$m258$,'79a9b6503c0d469f0c79d875061c561e'),
(23,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الأول: اجتماعات مجلس إدارة الجهاز ونظام العمل فيه > المادة 23$m258$,$m258$لا يجوز لأى عضو فى المجلس أن يشارك فى المداولات أو التصويت فى حالة معروضة على المجلس تكون له فيها مصلحة شخصية مباشرة ، أو غير مباشرة ، أو تكون بينه وبين أحد أطرافها صلة قرابة إلى الدرجة الرابعة أو يكون قد مثل أو يمثل أحد الأطراف فيها . ويلتزم عضو مجلس الإدارة بالإفصاح كتابة عن قيام أى من الدواعى المذكورة لديه ، وذلك قبل البدء فى المداولات أو التصويت بشأن الحالة المعروضة .$m258$,'b8ca7687cb58241c57af1a649ecda963'),
(24,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الأول: اجتماعات مجلس إدارة الجهاز ونظام العمل فيه > المادة 24$m258$,$m258$لمجلس الإدارة أن يدعو لحضور اجتماعاته من يرى الاستعانة به من المتخصصين وذلك دون أن يكون له صوت معدود فى التصويت .$m258$,'a2f1938e50991bd0e08835b4eb4b2abe'),
(25,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الأول: اجتماعات مجلس إدارة الجهاز ونظام العمل فيه > المادة 25$m258$,$m258$تدون محاضر اجتماعات مجلس الإدارة بصفة منتظمة فى دفتر خاص ، عقب كل جلسة ، ويوقع على هذه المحاضر من رئيس المجلس وأمين السر .$m258$,'ba2b42f31d14d38677b8a948faa4cadb'),
(26,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الثانى: اختصاصات مجلس الإدارة > المادة 26$m258$,$m258$يختص مجلس الإدارة بما يأتى :
( أ ) إبداء الرأى لمجلس الوزراء فى تحديد سعر بيع منتج أساسى أو أكثر لفترة زمنية محددة ، إعمالاً لحكم المادة ( 10 ) من القانون .
( ب ) قبول المنح والهبات وأية موارد أخرى تقدم إلى الجهاز ، وذلك بما لا يتعارض مع أهدافه .
( جـ ) وضع اللوائح المتعلقة بتنظيم العمل فى الجهاز ، وبالشئون المالية والإدارية للعاملين به ، دون التقيد بالقواعد والنظم المقررة للعاملين المدنيين بالدولة ، ورفعها إلى الوزير المختص لإصدارها .
( د ) اقتراح أسماء العاملين بالجهاز المطلوب منهم صفة الضبطية القضائية فى تطبيق أحكام القانون ، والذين يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع الوزير المختص .
( هـ ) اعتماد التقرير السنوى عن أنشطة الجهاز وخطته المستقبلية ومقترحاته .
( و ) إبداء الرأى فى مشروعات القوانين واللوائح المتعلقة بتنظيم المنافسة .
وذلك فضلاً عن الاختصاصات المنصوص عليها فى القانون ، وفى المواد الأخرى من هذه اللائحة .$m258$,'d9a7cc76e0d3c0c53bfaad9047757805'),
(27,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الثانى: اختصاصات مجلس الإدارة > المادة 27$m258$,$m258$لمجلس الإدارة أن يكلف أحد أعضائه أو لجنة تشكل من بينهم بالقيام بعمل معين أو بالإشراف على وجه من وجوه نشاط الجهاز ، وفى هذه الأحوال تعد تقارير عن العمل أو الإشراف تعرض على المجلس .$m258$,'bc6585d6e9dd07d9bba464fd1612597a'),
(28,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الثانى: اختصاصات مجلس الإدارة > المادة 28$m258$,$m258$يختص رئيس مجلس الإدارة بما يأتى :
( أ ) التنسيق مع الأجهزة النظيرة فى الدول الأخرى بالنسبة للأمور ذات الاهتمام المشترك ، وعرض التقارير المتصلة بذلك على مجلس الإدارة .
( ب ) إعداد تقرير سنوى عن أنشطة الجهاز ، وخطته المستقبلية ومقترحاته وعرضه على مجلس الإدارة لاعتماده .
( جـ ) ترشيح المدير التنفيذى للجهاز ، ورفع الترشيح إلى الوزير المختص .
( د ) الإشراف على تنظيم البرامج التدريبية والتثقيفية المتعلقة بالتوعية بأحكام القانون ومبادئ السوق الحر بوجه عام .
( هـ ) الإشراف على إصدار النشرات الدورية التى تتضمن القرارات والتوصيات والإجراءات والتدابير التى يتخذها الجهاز وغير ذلك مما يتصل بشئونه .$m258$,'5a1546e27006e3bd218fc5b978f1ed20'),
(29,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الثالث: الرسوم > المادة 29$m258$,$m258$يؤدى عن الطلب الخاص بالإخراج من نطاق الحظر المنصوص عليه فى المادة ( 9 ) من القانون ، وكذا الخاص بتجديد مدة سريان هذا الإخراج رسم مقداره عشرة آلاف جنيه ، ويتم سداد الرسم وإرفاق الإيصال الدال على السداد عند تقديم الطلب .$m258$,'3b4adff2138873777c8f5378cdb8aa88'),
(30,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السادس: جهاز حماية المنافسة ومنع الممارسات الاحتكارية > الفصل الثالث: الرسوم > المادة 30$m258$,$m258$يؤدى عن كل طلب من طلبات الاطلاع أو الحصول على شهادة أو صورة رسمية من أحد المستندات المسموح للجهاز بتداولها رسم مقداره مائة جنيه .$m258$,'d7f165cfc4ec0e3107edbfe1be45f55c'),
(31,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الأول: تقديم التبليغات > المادة 31$m258$,$m258$يجوز لأى شخص إبلاغ الجهاز بأية مخالفة لأحكام القانون . ولا يستحق الجهاز أية رسوم أو مقابل نظير تلقى البلاغ أو القيام بفحصه .$m258$,'afc334175f3a2bf8df1455f5e4743df6'),
(32,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الأول: تقديم التبليغات > المادة 32$m258$,$m258$يقدم البلاغ إلى الجهاز كتابة مشفوعاً بالبيانات والمستندات الآتية :
1 - اسم مقدم البلاغ وعنوانه وعمله وصفته ومصلحته فى تقديمه والمستندات المؤيدة لهذه البيانات .
2 - اسم المبلغ ضده وعنوانه وطبيعة نشاطه .
3 - نوع المخالفة المبلغ عنها .
4 - الدلائل التى يستند إليها البلاغ ، والمستندات المتصلة بها إن وجدت .
5 - بيان الضرر الواقع على المبلغ إن وجد .
وللجهاز أن يلتفت عن فحص أى بلاغ غير مستوف للبيانات والمستندات المشار إليها .$m258$,'faa9428eaef9c2bf943ced42fc0f0c69'),
(33,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 33$m258$,$m258$يتولى الجهاز فحص ما يقدم إليه من تبليغات ، وله دون حاجة لتقديم بلاغ اتخاذ إجراءات التقصى والبحث وجمع الاستدلالات وكذلك الأمر باتخاذ هذه الإجراءات وذلك بالنسبة لحالات الاتفاقات والممارسات الضارة بالمنافسة .$m258$,'82dd8ce0dd0a1c47db73ca4e5aedd112'),
(34,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 34$m258$,$m258$تكون إجراءات التقصى والبحث وجمع الاستدلالات بالنسبة لحالات الاتفاقات والممارسات الضارة بالمنافسة أو لأى مخالفة أخرى لأحكام القانون على النحو المبين فى المواد الآتية .$m258$,'5f8f416c4d711da5a0e804a18efd3125'),
(35,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 35$m258$,$m258$يتم قيد البلاغ عند تقديمه للجهاز فى السجل المعد لذلك ، ويعطى المبلغ إيصالاً برقم وتاريخ قيد البلاغ .
ويتم قيد الحالات التى يتولى الجهاز من تلقاء نفسه اتخاذ إجراءات التقصى والبحث وجمع الاستدلالات أو يأمر باتخاذ هذه الإجراءات فيها ، فى سجل آخر يعد لهذا الغرض .
ويثبت فى كل من السجلين بصفة منتظمة ما يتخذ من إجراءات فى الحالات المقيدة فيه ، وما يصدر فيها من قرارات أو أحكام .$m258$,'99095f15e5e3c8dc8e5e5f9f5d5027df'),
(36,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 36$m258$,$m258$تعرض التبليغات على المدير التنفيذى للجهاز للتحقق من استيفائها للبيانات والمستندات المنصوص عليها فى المادة ( 32 ) من هذه اللائحة ، وإحالة ما يكون مستوفياً منها إلى الإدارة المختصة وإخطار رئيس الجهاز بهذه الإحالة .$m258$,'d42fb92199908f4f8e5a68c00c3bc2a1'),
(37,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 37$m258$,$m258$تتولى الإدارة المختصة بالجهاز اتخاذ إجراءات التقصى والبحث وجمع الاستدلالات فى التبليغات المحالة إليها من المدير التنفيذى ، وذلك فى خلال مدة لا تجاوز تسعين يوماً من تاريخ الإحالة ، ويحرر محضر بجميع الإجراءات التى يتم اتخاذها .
ويكلف المدير التنفيذى الإدارة المذكورة باتخاذ الإجراءات المشار إليها فى الحالات التى يقرر فيها رئيس مجلس إدارة الجهاز ذلك .$m258$,'3307091731160caa5adf8aaef706ae26'),
(38,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 38$m258$,$m258$يكون للعاملين بالجهاز ممن لهم صفة الضبطية القضائية القيام بالإجراءات التالية وذلك بعد الكشف عن هويتهم واطلاع صاحب الشأن عليها :
1 - الاطلاع لدى أية جهة حكومية أو غير حكومية على الدفاتر والمستندات والحصول على المعلومات والبيانات اللازمة لفحص الحالات المعروضة على الجهاز .
2 - الدخول خلال ساعات العمل الرسمية إلى أماكن أو مقار عمل الأشخاص الخاضعين للفحص وذلك بعد الحصول على إذن كتابى من المدير التنفيذى ، ويجوز لهم الاستعانة برجال السلطة العامة إذا تطلب الأمر ذلك .
3 - اتخاذ إجراءات جمع الاستدلالات اللازمة للفحص وسؤال أى شخص فى شأن ارتكابه أية مخالفة لأحكام القانون .$m258$,'a1c91d15c908614c571ad410cb89de16'),
(39,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 39$m258$,$m258$تقوم الإدارة المختصة بعد إتمام إجراءات التقصى والبحث وجمع الاستدلالات بإعداد تقرير بالرأى تقدمه إلى المدير التنفيذى للجهاز . ويقوم المدير التنفيذى بعرضه على مجلس الإدارة ، مشفوعاً برأيه ، فى أول جلسة تالية لتقديم التقرير إليه .$m258$,'f3dd3ea5b2c9c57582de8e8edd0619a8'),
(40,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 40$m258$,$m258$لمجلس الإدارة بعد نظر التقرير الخاص بالحالة المعروضة أن يصدر قراراً مسبباً بحفظ الموضوع ، أو بإجراء مزيد من التقصى والبحث وجمع الاستدلالات بمعرفة الإدارة المختصة بالجهاز .$m258$,'ea2aa72c69bfb884675af75e92ab6f48'),
(41,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 41$m258$,$m258$على مجلس إدارة الجهاز عند ثبوت مخالفة لأحد الأحكام المنصوص عليها فى المواد ( 6 ) ، ( 7 ) ، ( 8 ) تكليف المخالف بتعديل أوضاعه وإزالة المخالفة فوراً أو خلال فترة زمنية يحددها المجلس .
ويتولى المدير التنفيذى للجهاز إخطار المخالف بهذا التكليف بموجب خطاب موصى عليه مصحوب بعلم الوصول .
وللمجلس أن يصدر قراراً بوقف الممارسات المحظورة فوراً ، أو بعد انقضاء الفترة الزمنية المشار إليها دون تعديل الأوضاع وإزالة المخالفة .$m258$,'eaea7dbae4ed74d9bfef9f05a8e562b9'),
(42,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 42$m258$,$m258$مع عدم الإخلال بحكم المادة ( 40 ) من هذه اللائحة يكون لمجلس الإدارة رفع التقرير الخاص بالحالة المعروضة إلى الوزير المختص أو من يفوضه لاتخاذ إجراءات طلب رفع الدعوى الجنائية .$m258$,'952bc7dca85aa5169ac167e26955a776'),
(43,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثانى: إجراءات التقصى والبحث وجمع الاستدلالات > المادة 43$m258$,$m258$يتولى المدير التنفيذى للجهاز إخطار الشخص أو الأشخاص ذوى الشأن بالقرار الذى ينتهى إليه مجلس الإدارة بشأن التبليغ أو الحالة المعروضة وذلك بموجب كتاب موصى عليه مصحوب بعلم الوصول .$m258$,'fe25e67d9cf35ad359532c3652c37262'),
(44,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثالث: تلقى الإخطارات > المادة 44$m258$,$m258$يكون تلقى الجهاز الإخطارات من الأشخاص ، خلال ثلاثين يوماً من اكتسابها أى أصول أو حقوق ملكية أو انتفاع أو أسهم ، أو إقامة اتحادات أو اندماجات أو دمج أو الجمع بين إدارة شخصين أو أكثر .$m258$,'80f23e735ffa9a62c65f34776db93f96'),
(45,0,$m258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005 > الباب السابع: تقديم التبليغات وإجراءات التقصى والبحث وجمع الاستدلالات وتلقى الإخطارات > الفصل الثالث: تلقى الإخطارات > المادة 45$m258$,$m258$يكون تقديم الإخطار إلى الجهاز كتابة ، ويجب أن يتضمن البيانات الآتية :
1 - أسماء مقدم الإخطار والأشخاص ذوى الصلة وجنسياتهم ومراكز إدارتهم والمراكز الرئيسية لأنشطتهم .
2 - التصرف القانونى المخطر به وتاريخه والوضع القانونى الناشئ عنه .
3 - بيان التراخيص والموافقات التى تم الحصول عليها .
ويجب أن يرفق بالإخطار كافة المستندات المؤيدة للبيانات المشار إليها .$m258$,'40480c453ed02ac10eb6426c8d191dde');

DO $m258$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_nover int;
BEGIN
  IF (SELECT count(*) FROM m258_art WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[258] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m258_art) <> 48 OR (SELECT sum(char_length(body)) FROM m258_art) <> 19625 THEN
    RAISE EXCEPTION '[258] عدد الصفوف أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=1316 AND law_year=2005 AND kind='regulation';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%المنافسة%' THEN
    RAISE EXCEPTION '[258] يوجد مستند آخر برقم 1316 لسنة 2005 من نوع regulation (%): لا تُدمج هذه اللائحة فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (1316, 2005, $t258$اللائحة التنفيذية لقانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005 (قرار رئيس مجلس الوزراء رقم 1316 لسنة 2005 - النص الأصلى المنشور فى 17/8/2005 قبل أى تعديلات)$t258$, $t258$اللائحة التنفيذية لقانون حماية المنافسة 1316/2005$t258$, 'other', 'amended', NULL, DATE '2005-08-16', NULL, 'EG', 'regulation', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m258_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
  SELECT a.id, 1, a.body, DATE '2005-08-18', 'active',
         $n258$النص الأصلى كما نشر فى الجريدة الرسمية العدد 32 مكرر فى 17/8/2005 (مواد 1 إلى 45 كما وردت فى الملف المرفوع)؛ عدل القانون 3/2005 لاحقا بالقانونين 190/2008 و175/2022 ولم تُرفع تعديلات اللائحة إن وجدت، فقد لا يطابق هذا النص الصيغة النافذة$n258$ || CASE WHEN a.article_suffix_order = 0 AND a.article_no IN (44, 45) THEN $x258$ - المادتان 44 و45 تتعلقان بالإخطار اللاحق خلال 30 يوماً من الاكتساب المرتبط بالفقرة الثانية من المادة 19 الأصلية من القانون، وقد ألغاها القانون 175/2022 وأحل محلها نظام الإخطار المسبق للتركز الاقتصادى؛ فلا يُعتد بهما قبل مراجعة اللائحة المعدلة$x258$ ELSE '' END
    FROM articles a JOIN m258_art m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m258_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 48 THEN
    RAISE EXCEPTION '[258] عدد صفوف اللائحة % بدل 48', v_cnt;
  END IF;
  SELECT count(*) INTO v_nover FROM articles a
   WHERE a.law_id=v_law AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id=a.id);
  IF v_nover <> 0 THEN
    RAISE EXCEPTION '[258] % صف بلا نسخة', v_nover;
  END IF;
  RAISE NOTICE '[258] لائحة 1316/2005: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m258$;
